<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { useForm } from 'vee-validate';
import { toTypedSchema } from '@vee-validate/zod';
import { loginSchema, registerSchema, password } from '@footlab/shared';
import { z } from 'zod';
import Button from 'primevue/button';
import { useAuth } from '../stores/auth';
import { api, errorMessage } from '../services/api';
const route = useRoute(), router = useRouter(), auth = useAuth(); const error = ref(''), message = ref('');
const mode = computed(() => ['register', 'forgot', 'reset'].includes(String(route.params.mode)) ? String(route.params.mode) : 'login');
const schema = computed(() => toTypedSchema(mode.value === 'register' ? registerSchema.extend({ organizationName: z.string().trim().max(120).refine(v => !v || v.length >= 2, 'Escribe al menos dos caracteres').optional() }) : mode.value === 'forgot' ? z.object({ email: z.string().email() }) : mode.value === 'reset' ? z.object({ password }) : loginSchema));
const { defineField, handleSubmit, errors, isSubmitting, resetForm } = useForm<{ email?: string; password?: string; name?: string; organizationName?: string }>({ validationSchema: schema as any });
const [email] = defineField('email'), [pass] = defineField('password'), [name] = defineField('name'), [organizationName] = defineField('organizationName');
watch(mode, () => { error.value = ''; message.value = ''; resetForm(); });
const submit = handleSubmit(async values => { error.value = ''; message.value = ''; try {
  if (mode.value === 'forgot') message.value = (await api.post('/auth/forgot-password', { email: values.email })).data.message;
  else if (mode.value === 'reset') { await api.post('/auth/reset-password', { token: route.query.token, password: values.password }); message.value = 'Contraseña actualizada. Ya puedes iniciar sesión.'; }
  else { await auth.signIn(mode.value as 'login' | 'register', mode.value === 'register' ? { name: values.name, email: values.email, password: values.password, ...(values.organizationName?.trim() ? { organizationName: values.organizationName.trim() } : {}) } : { email: values.email, password: values.password }); await router.replace('/'); }
} catch (e) { error.value = errorMessage(e); } });
</script>
<template><div class="auth-page"><section class="auth-story"><RouterLink class="brand" to="/">FOOTLAB<span class="brand-dot">.</span></RouterLink><div><span class="eyebrow">EL SIGUIENTE NIVEL DE TU FÚTBOL</span><h1>Cada jugada<br>cuenta una<br><em>historia.</em></h1><p>Encuentra la tuya en los datos. Analiza el juego, descubre talento y construye tu equipo.</p></div><div class="pitch-art"><div class="pitch-circle" /><span class="pitch-point p1" /><span class="pitch-point p2" /><span class="pitch-point p3" /><div class="pitch-line" /></div><span class="muted">PRO / CLUB / LAB</span></section><section class="auth-panel"><div class="auth-form"><span class="eyebrow">BIENVENIDO A FOOTLAB</span><h2>{{ { login: 'Vuelve al juego.', register: 'Empieza tu historia.', forgot: 'Recupera tu acceso.', reset: 'Una nueva contraseña.' }[mode] }}</h2><p class="muted">{{ mode === 'register' ? 'Crea tu cuenta y organiza tu primer club.' : 'Tu equipo y tus análisis, en un solo lugar.' }}</p><form @submit="submit"><label v-if="mode === 'register'">Tu nombre<input v-model="name" autocomplete="name"><small class="field-error">{{ errors.name }}</small></label><label v-if="mode === 'register'">Nombre del equipo o club (opcional)<input v-model="organizationName" autocomplete="organization" placeholder="Mi equipo"><small class="field-error">{{ errors.organizationName }}</small><small class="muted">Si te invitaron, deja este campo vacío y usa el código después de registrarte.</small></label><label v-if="mode !== 'reset'">Correo electrónico<input v-model="email" type="email" autocomplete="email" placeholder="tu@club.com"><small class="field-error">{{ errors.email }}</small></label><label v-if="mode !== 'forgot'">Contraseña<input v-model="pass" type="password" :autocomplete="mode === 'login' ? 'current-password' : 'new-password'" :placeholder="mode === 'login' ? 'Tu contraseña' : 'Al menos 12 caracteres'"><small class="field-error">{{ errors.password }}</small></label><RouterLink v-if="mode === 'login'" class="text-link forgot" to="/auth/forgot">Olvidé mi contraseña</RouterLink><div v-if="error" class="alert error" role="alert">{{ error }}</div><div v-if="message" class="alert success" role="status">{{ message }}</div><Button type="submit" class="button primary full" :loading="isSubmitting" :label="mode === 'login' ? 'Entrar a FOOTLAB' : mode === 'register' ? 'Crear mi cuenta' : 'Continuar'" icon="pi pi-arrow-right" icon-pos="right" /></form><p class="auth-switch"><template v-if="mode === 'login'">¿Es tu primera vez? <RouterLink to="/auth/register">Crear cuenta</RouterLink></template><RouterLink v-else to="/auth/login">Volver a iniciar sesión</RouterLink></p><div class="auth-note"><i aria-hidden="true" class="pi pi-lock" /> Tus datos de club pertenecen a tu organización.</div></div></section></div></template>
